import React from "react";

function IncomeCategory({ onNext }) {

  const handleSelect = (value) => {
    onNext(value); // ✅ FIXED
  };

  return (
    <div className="container">
      <h2>Select Income Category</h2>

      <button onClick={() => handleSelect("No Income")}>No Income</button>
      <button onClick={() => handleSelect("Low Income")}>Low Income</button>
      <button onClick={() => handleSelect("Medium Income")}>Medium Income</button>
      <button onClick={() => handleSelect("High Income")}>High Income</button>
    </div>
  );
}

export default IncomeCategory;
